// The AI only copies values. This node checks them, so a wrong total or a missing field
// is flagged for a person instead of going into the books.
const settings = $('Settings').item.json;
let ai = $json;
if (typeof ai.vendor !== 'string') {
  try {
    ai = JSON.parse(ai.text);
  } catch {
    ai = {};
  }
}

const toNumber = (v) => {
  if (typeof v === 'number') return v;
  const n = Number(String(v ?? '').replace(/[^0-9.-]/g, ''));
  return String(v ?? '').trim() === '' || Number.isNaN(n) ? null : n;
};
// The round trip rejects impossible days like 2026-02-30, which Date.parse quietly rolls over to March 2.
const toDate = (v) => {
  const s = String(v);
  const d = new Date(`${s}T00:00:00Z`);
  return /^\d{4}-\d{2}-\d{2}$/.test(s) && !Number.isNaN(d.getTime()) && d.toISOString().slice(0, 10) === s ? s : null;
};
// "Oct 31, 2026": never ambiguous like 10/31/2026, always UTC.
const pretty = (d) => (d ? new Date(`${d}T00:00:00Z`).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric', timeZone: 'UTC' }) : '-');
const money = (n) => (n === null ? '-' : n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }));

const inv = {
  vendor: String(ai.vendor || '').trim(),
  invoiceNumber: String(ai.invoice_number || '').trim(),
  invoiceDate: toDate(ai.invoice_date),
  dueDate: toDate(ai.due_date),
  currency: /^[A-Z]{3}$/.test(String(ai.currency)) ? String(ai.currency) : '',
  subtotal: toNumber(ai.subtotal),
  tax: toNumber(ai.tax) ?? 0,
  total: toNumber(ai.total),
};

const issues = [];
const unreadable = !inv.vendor && inv.total === null;
if (unreadable) {
  issues.push('The AI could not read this invoice. Please enter it by hand.');
} else {
  for (const [key, label] of [['vendor', 'Supplier'], ['invoiceNumber', 'Invoice number'], ['invoiceDate', 'Invoice date'], ['currency', 'Currency'], ['total', 'Total']]) {
    if (inv[key] === null || inv[key] === '') issues.push(`${label} is missing.`);
  }
}
if (inv.subtotal !== null && inv.total !== null && Math.abs(inv.subtotal + inv.tax - inv.total) > 0.01) {
  issues.push(`Totals don't add up: ${money(inv.subtotal)} + ${money(inv.tax)} tax = ${money(inv.subtotal + inv.tax)}, but the invoice says ${money(inv.total)}.`);
}
const today = new Date().toISOString().slice(0, 10);
const overdue = Boolean(inv.dueDate && inv.dueDate < today);
const fileName = $('Upload invoice').item.binary?.invoice?.fileName || 'invoice.pdf';
const totalText = `${inv.currency} ${money(inv.total)}`.trim();

const emailSubject = unreadable
  ? `[CHECK] Invoice could not be read: ${fileName}`
  : `${issues.length ? '[CHECK] ' : ''}Invoice from ${inv.vendor || 'unknown supplier'}: ${totalText}, due ${pretty(inv.dueDate)}${overdue ? ' (OVERDUE)' : ''}`;
const emailBody = [
  issues.length
    ? `Please check this invoice before paying:\n${issues.map((x) => `- ${x}`).join('\n')}\n`
    : 'All checks passed. Ready to pay.\n',
  overdue ? 'Note: the due date has already passed.\n' : null,
  `Supplier:        ${inv.vendor || '-'}`,
  `Invoice number:  ${inv.invoiceNumber || '-'}`,
  `Invoice date:    ${pretty(inv.invoiceDate)}`,
  `Due date:        ${pretty(inv.dueDate)}`,
  `Subtotal:        ${money(inv.subtotal)}`,
  `Tax:             ${unreadable ? '-' : money(inv.tax)}`,
  `Total:           ${totalText}`,
  '',
  `File: ${fileName}`,
  'The attached CSV row imports straight into Excel, Google Sheets or your accounting software.',
].filter((line) => line !== null).join('\n');

return {
  json: {
    ...inv,
    needsReview: issues.length > 0,
    issues,
    overdue,
    emailSubject,
    emailBody,
    accountsEmail: settings.accountsEmail,
    botEmail: settings.botEmail,
  },
};
